def allocation_state(actions):
    rows = []
    high = 0
    saved_rows = []
    saved_high = 0
    for action in actions:
        op = action["op"]
        if op == "put":
            rows.append(action["id"])
            high = max(high, action["id"])
        elif op == "delete":
            if action["id"] in rows:
                rows.remove(action["id"])
        elif op == "begin":
            saved_rows = list(rows)
            saved_high = high
        elif op == "rollback":
            rows = list(saved_rows)
            high = saved_high
    return {"rows": rows, "high": high}

def next_id(state):
    return max(state["rows"] + [state["high"], 0]) + 1

def investigate(context, acquire):
    return next_id(allocation_state(context["actions"]))

def investigate(context, acquire):
    order = []
    hits = 0
    misses = 0
    for event in context["events"]:
        if event["op"] == "reset":
            order = []
            hits = 0
            misses = 0
        else:
            key = event["key"]
            if key in order:
                hits += 1
                order.remove(key)
            else:
                misses += 1
            order.append(key)
            if len(order) > context["capacity"]:
                order.pop(0)
    return {"hits": hits, "misses": misses, "size": len(order)}
